            this.linear = true;
        }

        this.errorMessageElement = this.element.querySelector('.error-message');
        this.errorMessageTextElement = this.errorMessageElement.querySelector('.error-text');

        this.onChange = new Event();

        this.numberInput.addEventListener('change', (e) => {
            this.value = this.numberInput.value;
            this.onChange.invoke(this.value);
        });

